<template><section class="section"><div class="container-page max-w-2xl"><h1 class="text-4xl">Book a Site Inspection</h1><p class="mt-3 text-neutral-600">Choose a convenient date to visit the property with Lexshield.</p><form class="card mt-8 space-y-5 p-6" @submit.prevent="submit"><div><label class="label">Property</label><select v-model="form.property_id" class="input" required @change="syncProperty"><option value="">Select a property</option><option v-for="item in properties" :key="item.id" :value="item.id">{{ item.name }} — {{ item.city }}</option></select></div><div v-if="selectedProperty"><label class="label">Plot option (optional)</label><select v-model="form.plot_option_id" class="input" @change="syncOption"><option value="">Not sure</option><option v-for="option in selectedProperty.property_plot_options" :key="option.id" :value="option.id">{{ option.label }}</option></select></div><div v-if="selectedOption"><label class="label">Payment plan (optional)</label><select v-model="form.payment_plan_id" class="input" @change="syncPlan"><option value="">Not sure</option><option v-for="plan in selectedOption.property_payment_plans" :key="plan.id" :value="plan.id">{{ plan.label }} — {{ money(plan.price) }}</option></select></div><div class="grid gap-5 sm:grid-cols-2"><div><label class="label">Name</label><input v-model="form.name" class="input" required /></div><div><label class="label">Phone</label><input v-model="form.phone" class="input" type="tel" required /></div><div><label class="label">Email</label><input v-model="form.email" class="input" type="email" /></div><div><label class="label">Preferred date</label><input v-model="form.preferred_date" class="input" type="date" :min="today" required /></div></div><p v-if="message" class="rounded-lg bg-success-50 p-3 text-success-800">{{ message }}</p><button class="btn-primary w-full" :disabled="submitting">{{ submitting ? 'Submitting…' : 'Request Inspection' }}</button></form></div></section></template>
<script setup lang="ts">
const route=useRoute(); const {list}=useProperties(); const {data:properties}=useAsyncData('inspection-properties',()=>list()); const submitting=ref(false); const message=ref(''); const today=new Date().toISOString().slice(0,10); const form=reactive({name:'',phone:'',email:'',preferred_date:'',property_id:'',property_name:'',property_location:'',plot_option_id:'',plot_option_label:'',payment_plan_id:'',payment_plan_label:'',displayed_price:null as number|null}); const selectedProperty=computed(()=>properties.value?.find(item=>item.id===form.property_id));const selectedOption=computed(()=>selectedProperty.value?.property_plot_options?.find(item=>item.id===form.plot_option_id));
function syncProperty(){form.property_name=selectedProperty.value?.name||'';form.property_location=selectedProperty.value?.location_name||'';form.plot_option_id='';form.plot_option_label='';form.payment_plan_id='';form.payment_plan_label='';form.displayed_price=null} function syncOption(){form.plot_option_label=selectedOption.value?.label||'';form.payment_plan_id='';form.payment_plan_label='';form.displayed_price=null} function syncPlan(){const plan=selectedOption.value?.property_payment_plans?.find(item=>item.id===form.payment_plan_id);form.payment_plan_label=plan?.label||'';form.displayed_price=plan?.price||null} const money=(value:number)=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(value)
watch(properties,items=>{const match=items?.find(item=>item.slug===route.query.property);if(match){form.property_id=match.id;syncProperty();if(route.query.plot){form.plot_option_id=String(route.query.plot);syncOption();if(route.query.plan){form.payment_plan_id=String(route.query.plan);syncPlan()}}}},{immediate:true}); async function submit(){submitting.value=true;try{const {error}=await useSupabase().from('inspection_bookings').insert({...form,plot_option_id:form.plot_option_id||null,payment_plan_id:form.payment_plan_id||null,email:form.email||null,source:'property_page'});if(error)throw error;message.value='Your inspection request has been received. Lexshield will contact you shortly.';if(import.meta.client)window.dataLayer?.push({event:'inspection_submitted',property_name:form.property_name,location:form.property_location,plot_option:form.plot_option_label,payment_plan:form.payment_plan_label})}finally{submitting.value=false}}
useSeoMeta({title:'Book a Site Inspection | Lexshield Properties',description:'Book a site inspection for a Lexshield property.'})
</script>
